package ar.com.liftmanager.controller;
import ar.com.liftmanager.dto.ApiDtos.*;import ar.com.liftmanager.service.ClaimService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/claims") public class ClaimController {private final ClaimService service;public ClaimController(ClaimService s){service=s;}@GetMapping public List<ClaimView> list(){return service.list();}@PostMapping public ClaimView create(@Valid @RequestBody ClaimRequest r){return service.create(r);}@PatchMapping("/{id}/assign") public ClaimView assign(@PathVariable Long id,@Valid @RequestBody AssignClaimRequest r){return service.assign(id,r);}@PatchMapping("/{id}/status") public ClaimView status(@PathVariable Long id,@Valid @RequestBody ClaimStatusRequest r){return service.status(id,r);}}
